window.VO = [{"id":"n01","text":"You're the passport officer, and one of these five men is flying on someone else's passport.","at":0.24,"t0":0.12,"t1":5.1},{"id":"n02","text":"Whoever you stop will miss his flight.","at":10.9,"t0":5.45,"t1":7.29},{"id":"n03","text":"So who do you stop?","at":16.4,"t0":8.2,"t1":9.355},{"id":"n04","text":"Were you that sure?","at":28.11,"t0":14.055,"t1":15.055},{"id":"n05","text":"Because in a real test, passport officers waved through one lookalike in seven.","at":31.61,"t0":15.805,"t1":20.305},{"id":"n06","text":"Number two is going home for the first time in nine years, and his photo's from the year he left.","at":42.01,"t0":21.005,"t1":26.455},{"id":"n07","text":"If you stopped him, he's in a back room now, holding his own passport.","at":54.31,"t0":27.155,"t1":30.865},{"id":"m08a","text":"That's me.","at":62.93,"t0":31.465,"t1":32.33},{"id":"m08b","text":"I just got old.","at":65.58,"t0":32.79,"t1":34.01},{"id":"n09","text":"So who was it?","at":69.22,"t0":34.61,"t1":35.61},{"id":"n10","text":"Number four matched his photo almost perfectly, but it isn't his.","at":73.22,"t0":36.61,"t1":40.285},{"id":"n11","text":"It's his brother's.","at":81.47,"t0":40.735,"t1":41.835},{"id":"n12","text":"Unless you stopped him, he's boarding now, as his brother.","at":85.47,"t0":42.735,"t1":45.82},{"id":"n13","text":"Now look again.","at":94.24,"t0":47.12,"t1":48.1},{"id":"n14","text":"What gave him away?","at":97.64,"t0":48.82,"t1":49.94}];
